package com.gerenciadorrural.modules.farms.infrastructure;
import com.gerenciadorrural.modules.farms.domain.*; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.dao.IncorrectResultSizeDataAccessException; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JdbcFarmProfileQueryRepository implements FarmProfileQueryRepository {private final NamedParameterJdbcTemplate jdbc;public JdbcFarmProfileQueryRepository(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;}public Optional<FarmProfile> findCurrent(TenantId t,UUID f){return rows("select f.id,f.tenant_id,f.name,f.status,f.version from app.farms f where f.id=:farmId and f.tenant_id=:tenantId and f.status='ACTIVE'",t,f,null,-1).stream().findFirst();}public FarmProfileUpdateResult updateName(TenantId t,UUID f,String n,long v){var updated=rows("update app.farms set name=:name,version=version+1,updated_at=current_timestamp where id=:farmId and tenant_id=:tenantId and status='ACTIVE' and version=:expectedVersion returning id,tenant_id,name,status,version",t,f,n,v);if(!updated.isEmpty())return new FarmProfileUpdateResult.Updated(updated.getFirst());return findCurrent(t,f).isPresent()?new FarmProfileUpdateResult.VersionConflict():new FarmProfileUpdateResult.NotAvailable();}private List<FarmProfile> rows(String s,TenantId t,UUID f,String n,long v){var p=new MapSqlParameterSource().addValue("tenantId",t.value()).addValue("farmId",f);if(n!=null)p.addValue("name",n).addValue("expectedVersion",v);var r=jdbc.query(s,p,(x,i)->new FarmProfile(x.getObject("id",UUID.class),new TenantId(x.getObject("tenant_id",UUID.class)),x.getString("name"),x.getString("status"),x.getLong("version")));if(r.size()>1)throw new IncorrectResultSizeDataAccessException(1,r.size());return r;}}
